#include <string.h>

#include "keccak.h"

#if defined(__thumb2__)

// Thumb-2, generated by scripts/gen_asm.py (keccak_thumb2.S): a loop of one round on the
// bit-interleaved state (64-bit rotations become 32-bit ones), small enough for the core's
// ~2 KB instruction cache, reading the round constants from a RAM copy of keccak_rc; and
// the one-block hash around it (interleaving in and out, padding).
void                  keccakf1600_asm(uint32_t s[50], const uint32_t *rc);
void                  keccak256_oneblock16_asm(uint32_t out[4], const uint32_t block[16], uint32_t len,
                                               const uint32_t *rc);
extern const uint32_t keccak_rc[48];

static uint32_t g_rc[48];

void keccak_setup(void) {
    memcpy(g_rc, keccak_rc, sizeof(g_rc));
}

void keccak_permute(uint32_t s[50]) {
    keccakf1600_asm(s, g_rc);
}

void keccak256_oneblock16(uint32_t out[4], const uint32_t block[16], uint32_t len) {
    keccak256_oneblock16_asm(out, block, len, g_rc);
}

// Even bits of x to the low half, odd bits to the high half (and back).
static inline uint32_t unzip(uint32_t x) {
    uint32_t t;
    t = (x ^ (x >> 1)) & 0x22222222u, x ^= t ^ (t << 1);
    t = (x ^ (x >> 2)) & 0x0C0C0C0Cu, x ^= t ^ (t << 2);
    t = (x ^ (x >> 4)) & 0x00F000F0u, x ^= t ^ (t << 4);
    t = (x ^ (x >> 8)) & 0x0000FF00u, x ^= t ^ (t << 8);
    return x;
}

static inline uint32_t zip(uint32_t x) {
    uint32_t t;
    t = (x ^ (x >> 8)) & 0x0000FF00u, x ^= t ^ (t << 8);
    t = (x ^ (x >> 4)) & 0x00F000F0u, x ^= t ^ (t << 4);
    t = (x ^ (x >> 2)) & 0x0C0C0C0Cu, x ^= t ^ (t << 2);
    t = (x ^ (x >> 1)) & 0x22222222u, x ^= t ^ (t << 1);
    return x;
}

void keccak_absorb(uint32_t s[50], const uint32_t *in, uint32_t n_words) {
    for (uint32_t i = 0; i < n_words; i += 2) {
        uint32_t lo = unzip(in[i]);
        uint32_t hi = i + 1 < n_words ? unzip(in[i + 1]) : 0;
        s[i] ^= (lo & 0xFFFF) | (hi << 16);
        s[i + 1] ^= (lo >> 16) | (hi & 0xFFFF0000u);
    }
}

// Byte p's bit 0 is lane bit 8 (p % 8), an even bit; byte 135's bit 7 is lane 16's bit 63.
void keccak_pad(uint32_t s[50], uint32_t n_bytes) {
    s[2 * (n_bytes / 8)] ^= 1u << (4 * (n_bytes % 8));
    s[33] ^= 0x80000000u;
}

void keccak_squeeze(uint32_t *out, const uint32_t s[50], uint32_t n_words) {
    for (uint32_t i = 0; i < n_words; i += 2) {
        out[i] = zip((s[i] & 0xFFFF) | (s[i + 1] << 16));
        out[i + 1] = zip((s[i] >> 16) | (s[i + 1] & 0xFFFF0000u));
    }
}

#else

// Portable C (host builds, tests/native): plain 64-bit lanes, little-endian host.

static const uint64_t RC[24] = {
    0x0000000000000001ull, 0x0000000000008082ull, 0x800000000000808Aull, 0x8000000080008000ull,
    0x000000000000808Bull, 0x0000000080000001ull, 0x8000000080008081ull, 0x8000000000008009ull,
    0x000000000000008Aull, 0x0000000000000088ull, 0x0000000080008009ull, 0x000000008000000Aull,
    0x000000008000808Bull, 0x800000000000008Bull, 0x8000000000008089ull, 0x8000000000008003ull,
    0x8000000000008002ull, 0x8000000000000080ull, 0x000000000000800Aull, 0x800000008000000Aull,
    0x8000000080008081ull, 0x8000000000008080ull, 0x0000000080000001ull, 0x8000000080008008ull,
};

// Rotation of lane x + 5 y.
static const uint8_t RHO[25] = {0, 1, 62, 28, 27, 36, 44, 6, 55, 20, 3, 10, 43, 25, 39, 41, 45, 15, 21, 8, 18, 2, 61, 56, 14};

static inline uint64_t rotl64(uint64_t x, unsigned n) {
    return n ? (x << n) | (x >> (64 - n)) : x;
}

void keccak_setup(void) {}

void keccak_permute(uint32_t s[50]) {
    uint64_t a[25], b[25], c[5], d;
    memcpy(a, s, sizeof(a));
    for (unsigned r = 0; r < 24; r++) {
        for (unsigned x = 0; x < 5; x++) {
            c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20];
        }
        for (unsigned x = 0; x < 5; x++) {
            d = c[(x + 4) % 5] ^ rotl64(c[(x + 1) % 5], 1);
            for (unsigned y = 0; y < 25; y += 5) {
                a[x + y] ^= d;
            }
        }
        // rho and pi: B[y, 2x + 3y] = rotl(A[x, y], RHO[x, y]).
        for (unsigned x = 0; x < 5; x++) {
            for (unsigned y = 0; y < 5; y++) {
                b[y + 5 * ((2 * x + 3 * y) % 5)] = rotl64(a[x + 5 * y], RHO[x + 5 * y]);
            }
        }
        for (unsigned y = 0; y < 25; y += 5) {
            for (unsigned x = 0; x < 5; x++) {
                a[x + y] = b[x + y] ^ (~b[(x + 1) % 5 + y] & b[(x + 2) % 5 + y]);
            }
        }
        a[0] ^= RC[r];
    }
    memcpy(s, a, sizeof(a));
}

void keccak_absorb(uint32_t s[50], const uint32_t *in, uint32_t n_words) {
    for (uint32_t i = 0; i < n_words; i++) {
        s[i] ^= in[i];
    }
}

void keccak_pad(uint32_t s[50], uint32_t n_bytes) {
    ((uint8_t *) s)[n_bytes] ^= 0x01;
    ((uint8_t *) s)[135] ^= 0x80;
}

void keccak_squeeze(uint32_t *out, const uint32_t s[50], uint32_t n_words) {
    memcpy(out, s, 4 * n_words);
}

void keccak256_oneblock16(uint32_t out[4], const uint32_t block[16], uint32_t len) {
    uint32_t s[50];
    memset(s, 0, sizeof(s));
    keccak_absorb(s, block, (len + 3) / 4);
    keccak_pad(s, len);
    keccak_permute(s);
    keccak_squeeze(out, s, 4);
}

#endif
